fn arccos(x: Vec<i8>) -> Vec<i8> {
    // Prepare an output vector with the same length as the input
    let mut result = Vec::with_capacity(x.len());

    // Transform each element according to the specified rules:
    // - If input == -1, output = 3
    // - If input ==  1, output = 0
    // - If input ==  0, we choose output = 1 (any value in 0..=3 is acceptable)
    for xi in x {
        let yi = match xi {
            -1 => 3,
             0 => 1,
             1 => 0,
             _ => panic!("Input out of expected range [-1, 1]: {}", xi),
        };
        result.push(yi);
    }

    result
}

